import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"CDS Squid: RGW","description":"","frontmatter":{"title":"CDS Squid: RGW","date":"2023-07-25T00:00:00.000Z","updated":"2023-07-26T00:00:00.000Z","tags":["Ceph","RGW","分布式存储","CephFS","RadosGW"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/CDS_Squid_-_RGW.md","filePath":"posts/2023/CDS_Squid_-_RGW.md","lastUpdated":1780459816000}'),o={name:"posts/2023/CDS_Squid_-_RGW.md"};function r(s,l,n,u,p,h){return a(),e("div",null,[...l[0]||(l[0]=[t('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><p>Ceph RGW 会议的目的是讨论Ceph S版本的规划，并分享当前正在进行的一些项目。以下是对会议内容的总结：</p><h3 id="会议目的" tabindex="-1">会议目的 <a class="header-anchor" href="#会议目的" aria-label="Permalink to &quot;会议目的&quot;">​</a></h3><ul><li>讨论Ceph S版本的规划。</li><li>分享当前正在进行的一些项目。</li><li>将讨论内容更新到Ceph的Trello看板中。</li></ul><h3 id="主要议题与讨论内容" tabindex="-1">主要议题与讨论内容 <a class="header-anchor" href="#主要议题与讨论内容" aria-label="Permalink to &quot;主要议题与讨论内容&quot;">​</a></h3><ol><li><p><strong>D4N数据缓存项目</strong></p><ul><li>讨论了D4N数据缓存项目的进展，预计在S版本中包含增加灵活性和访问缓存目录的额外功能。</li></ul></li><li><p><strong>Aeroflight集成</strong></p><ul><li>探讨了Aeroflight的前端集成，目标是实现端到端的概念验证。</li></ul></li><li><p><strong>POSIX文件后端和独立RGW部署</strong></p><ul><li>开发基于POSIX文件系统的RGW后端，并探索独立RGW部署的可能性。</li></ul></li><li><p><strong>跟踪（Tracing）</strong></p><ul><li>使用Jaeger和OpenTracing库进行集成，计划扩展跟踪覆盖范围。</li></ul></li><li><p><strong>标记的Prometheus指标</strong></p><ul><li>目标是支持按用户或存储桶过滤RGW的计数器。</li></ul></li><li><p><strong>多站点（Multi-site）</strong></p><ul><li>计划将存储桶索引日志从omap移出，并产品化归档区域同步模块。</li></ul></li><li><p><strong>异步重构</strong></p><ul><li>持续进行异步模型的转换，减少RGW线程池的大小，并探索基于C++20协程的多站点原型。</li></ul></li><li><p><strong>QoS集成与Libreidos</strong></p><ul><li>利用OSD中的QoS功能，确保客户端请求和后台工作的公平性。</li></ul></li><li><p><strong>测试</strong></p><ul><li>强调在错误和延迟情况下的改进测试，包括使用Warp工具和其他测试方法。</li></ul></li><li><p><strong>生产检查工具</strong></p><ul><li>讨论了实时统计工具的需求，以帮助快速识别和解决性能问题。</li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>所有讨论的内容将被整理并更新到Ceph的Trello看板中。</li><li>将继续推进各个项目的开发和集成工作。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>继续进行D4N数据缓存项目的开发和集成。</li><li>探索和实现Aeroflight的前端集成。</li><li>开发和测试基于POSIX文件系统的RGW后端。</li><li>扩展跟踪功能，特别是在多站点复制中。</li><li>进行标记的Prometheus指标的规模测试。</li><li>推进多站点功能的开发和产品化。</li><li>完成异步重构和QoS集成工作。</li><li>加强错误和性能测试，确保软件质量和性能。</li></ul><h3 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h3><p>会议结束时，主持人确保所有讨论内容将被整理并更新到Trello看板中，并对所有参与者表示感谢。</p>',12)])])}const g=i(o,[["render",r]]);export{_ as __pageData,g as default};
